            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">  StripeTerminal,</span>",
            "<span style=\"color:#E1E4E8\">  TerminalConnectTypes,</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum,</span>",
            "<span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-terminal'</span><span style=\"color:#E1E4E8\">;</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> paymentStatusListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.PaymentStatusChange,</span>",
            "<span style=\"color:#E1E4E8\">  ({ </span><span style=\"color:#FFAB70\">status</span><span style=\"color:#E1E4E8\"> }) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(status),</span>",
            "<span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> confirmedListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.ConfirmedPaymentIntent,</span>",
            "<span style=\"color:#E1E4E8\">  () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Payment processed; waiting for the server webhook'</span><span style=\"color:#E1E4E8\">),</span>",
            "<span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> failedListener</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.Failed,</span>",
            "<span style=\"color:#E1E4E8\">  (</span><span style=\"color:#FFAB70\">error</span><span style=\"color:#E1E4E8\">) </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> console.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">(error),</span>",
            "<span style=\"color:#E1E4E8\">);</span>",
            "",
            "<span style=\"color:#a0aab5\">// Register the authenticated RequestedConnectionToken provider first.</span>",
            "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">({ isTest: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\"> });</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">readers</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">discoverReaders</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">  type: TerminalConnectTypes.TapToPay,</span>",
            "<span style=\"color:#E1E4E8\">  locationId: </span><span style=\"color:#9ECBFF\">'**************'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">});</span>",
            "",
            "<span style=\"color:#F97583\">const</span><span style=\"color:#79B8FF\"> reader</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> readers[</span><span style=\"color:#79B8FF\">0</span><span style=\"color:#E1E4E8\">];</span>",
            "<span style=\"color:#F97583\">if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">reader) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'No compatible reader found'</span><span style=\"color:#E1E4E8\">);</span>",
            "",
            "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">connectReader</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">  reader,</span>",
            "<span style=\"color:#E1E4E8\">});</span>",
            "",
            "<span style=\"color:#F97583\">try</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'https://example.com/connection/intent'</span><span style=\"color:#E1E4E8\">, {</span>",
            "<span style=\"color:#E1E4E8\">    method: </span><span style=\"color:#9ECBFF\">'POST'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">    headers: { Authorization: </span><span style=\"color:#9ECBFF\">`Bearer ${</span><span style=\"color:#E1E4E8\">accessToken</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\"> },</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">response.ok) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`PaymentIntent request failed: ${</span><span style=\"color:#E1E4E8\">response</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">status</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">paymentIntent</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">as</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#FFAB70\">paymentIntent</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\"> };</span>",
            "",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">collectPaymentMethod</span><span style=\"color:#E1E4E8\">({ paymentIntent });</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">confirmPaymentIntent</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#E1E4E8\">} </span><span style=\"color:#F97583\">finally</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">disconnectReader</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#E1E4E8\">}</span>",
            "",
